<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Namma Metro Fare Calculator 2026</title>
    <style>
        .metro-calc-container {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background-color: #f9f9f9;
            border: 2px solid #008751;
            border-radius: 10px;
            padding: 25px;
            max-width: 450px;
            margin: 20px auto;
            box-shadow: 0 4px 10px rgba(0,0,0,0.1);
        }
        .metro-calc-title {
            color: #008751;
            text-align: center;
            margin-top: 0;
            font-size: 1.5rem;
            font-weight: 700;
            border-bottom: 2px solid #9b26b6;
            padding-bottom: 10px;
        }
        .calc-group {
            margin-bottom: 15px;
        }
        .calc-group label {
            display: block;
            margin-bottom: 5px;
            font-weight: 600;
            color: #333;
        }
        .calc-group select {
            width: 100%;
            padding: 10px;
            border: 1px solid #ccc;
            border-radius: 5px;
            font-size: 1rem;
            background-color: #fff;
        }
        .calc-btn {
            width: 100%;
            background-color: #008751;
            color: white;
            border: none;
            padding: 12px;
            font-size: 1.1rem;
            font-weight: bold;
            border-radius: 5px;
            cursor: pointer;
            transition: background 0.3s ease;
        }
        .calc-btn:hover {
            background-color: #00643c;
        }
        .calc-results {
            margin-top: 20px;
            background-color: #fff;
            border-left: 5px solid #9b26b6;
            padding: 15px;
            border-radius: 4px;
            display: none;
        }
        .result-item {
            display: flex;
            justify-content: space-between;
            margin-bottom: 8px;
            font-size: 1rem;
        }
        .result-item:last-child {
            margin-bottom: 0;
        }
        .result-val {
            font-weight: bold;
            color: #008751;
        }
        .purple-text {
            color: #9b26b6 !important;
        }
    </style>
</head>
<body>

<div class="metro-calc-container">
    <div class="metro-calc-title">Namma Metro Cost Estimator (2026)</div>

    <div class="calc-group">
        <label for="distanceRange">Estimated Travel Distance:</label>
        <select id="distanceRange">
            <option value="11">Short hop (0 – 2 km)</option>
            <option value="21">Nearby commute (2 – 4 km)</option>
            <option value="32">Quick ride (4 – 6 km)</option>
            <option value="42">Moderate distance (6 – 8 km)</option>
            <option value="53">Standard commute (8 – 10 km)</option>
            <option value="63">Mid-long commute (10 – 15 km)</option>
            <option value="74">Long distance (15 – 20 km)</option>
            <option value="84">Suburban link (20 – 25 km)</option>
            <option value="95">City cross / End-to-End (Above 25 km)</option>
        </select>
    </div>

    <div class="calc-group">
        <label for="timeType">Time / Day of Travel:</label>
        <select id="timeType">
            <option value="peak">Weekday Peak Hours (5% Card Disc.)</option>
            <option value="offpeak">Weekday Off-Peak Hours (10% Card Disc.)</option>
            <option value="sunday">Sunday / National Holiday (10% Card Disc.)</option>
        </select>
    </div>

    <button class="calc-btn" onclick="calculateMetroFare()">Estimate Trip Cost</button>

    <div class="calc-results" id="fareResults">
        <div class="result-item">
            <span>Single Journey Token Fare:</span>
            <span class="result-val" id="tokenFare">₹0</span>
        </div>
        <div class="result-item">
            <span>Smart Card / NCMC Fare:</span>
            <span class="result-val purple-text" id="cardFare">₹0</span>
        </div>
        <div class="result-item" style="font-size: 0.85rem; color: #666; margin-top: 10px; font-style: italic;">
            *Note: Smart card fares are rounded to the nearest rupee. Minimum gate balance required is ₹90.
        </div>
    </div>
</div>

<script>
    function calculateMetroFare() {
        const baseFare = parseFloat(document.getElementById('distanceRange').value);
        const timeType = document.getElementById('timeType').value;

        let discount = 0.05; // Default peak hour 5%
        if (timeType === 'offpeak' || timeType === 'sunday') {
            discount = 0.10; // 10% off-peak/holiday discount
        }

        const calculatedCardFare = Math.round(baseFare * (1 - discount));

        document.getElementById('tokenFare').innerText = '₹' + baseFare;
        document.getElementById('cardFare').innerText = '₹' + calculatedCardFare;
        document.getElementById('fareResults').style.display = 'block';
    }
</script>

</body>
</html>

